INSERT INTO `lueg_ausbildung_items` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `starttime`, `endtime`, `fe_group`, `sorting`, `editlock`, `sys_language_uid`, `l10n_parent`, `l10n_source`, `l10n_state`, `l10n_diffsource`, `t3ver_oid`, `t3ver_wsid`, `t3ver_state`, `t3ver_stage`, `title`, `content`, `foreign_table_parent_uid`) VALUES
(1, 1, 1785996509, 1785502894, 0, 0, 0, 0, '', 1, 0, 0, 0, 0, NULL, 0x7b22636f6e74656e74223a22222c22656469746c6f636b223a22222c22656e6474696d65223a22222c2266655f67726f7570223a22222c2268696464656e223a22222c22737461727474696d65223a22222c227469746c65223a22227d, 0, 0, 0, 0, 'Voraussetzungen FaGe', '<p><strong>Voraussetzungen FaGe Lehre</strong></p>\r\n<ul><li data-list-item-id=\"e378522b5fd3817e204d231e18a896c08\">Abgeschlossene obligatorische Schulzeit</li><li data-list-item-id=\"eb0b4d375d6b9a81b8bf691a5727dcfe2\">Einfühlungsvermögen, wertschätzende Grundhaltung und Freude an der Kommunikation</li><li data-list-item-id=\"ee1e438cf4c182c8d422e28bf908b4bb6\">Aufmerksamkeit und Sorgfalt</li><li data-list-item-id=\"ecf3c6621fdedca1f89d0bd88736e1d1c\">Flexibilität und Organisationstalent</li><li data-list-item-id=\"e1675db02db4bce2d285e2771b5b77466\">Verantwortungsbewusstsein</li><li data-list-item-id=\"e3f8ca5bb1c96187b9696dd73ce9f2f3e\">Freude mit hoher Selbständigkeit und im Team zu arbeiten</li><li data-list-item-id=\"e0d402a34bd785928815742fcbda596bc\">Belastbarkeit</li><li data-list-item-id=\"e7450638fb1d37dc29b77dafc1e364006\">Bereitschaft, sobald als möglich die Autoprüfung zu absolvieren<br>&nbsp;</li></ul>\r\n<p><strong>Voraussetzungen FaGe E (verkürzte Lehre für Erwachsene)</strong></p>\r\n<ul><li data-list-item-id=\"eb44665fe731bbc479123d81973a72d85\">Mindestens 22 Jahre alt</li><li data-list-item-id=\"ef15ab3516e7903e712e85160a0390bcd\">Mindestens 2 Jahre zu 60 Prozent oder mehr im Berufsfeld Pflege und Betreuung gearbeitet</li><li data-list-item-id=\"e60d3dd231256f50255d39c90ecc5e9d6\">Ausnahme: Abschluss Pflegeassistentin: 1 Jahr Arbeitserfahrung</li><li data-list-item-id=\"ebfe6f1c01f9bfd60f4522f2a105e5498\">Gute Deutschkenntnisse</li><li data-list-item-id=\"e3c82f6f7ba46d58eaacee47b9b7795b6\">Gute mündliche und schriftliche Ausdrucksfähigkeit</li><li data-list-item-id=\"ea9a85af9bf1394a4101b4721b42c598e\">Abschluss Allgemeinbildung (ABU)</li></ul>\r\n\r\n<p class=\"text-small\">Weitere Informationen zur Ausbildung findest du auf der Plattform <a href=\"https://gesundheitsberufe-bern.ch/\" target=\"_blank\">Gesundheitsberufe Kanton Bern</a> und unter <a href=\"https://www.spitexbe.ch/de/ausbildung/fachfrau-fachmann-gesundheit-efz-fage\" target=\"_blank\">FaGe-Ausbildung</a> bei der Spitex</p>', 3),
(2, 1, 1785996509, 1785502894, 0, 0, 0, 0, '', 2, 0, 0, 0, 0, NULL, 0x7b22636f6e74656e74223a22222c22656469746c6f636b223a22222c22656e6474696d65223a22222c2266655f67726f7570223a22222c2268696464656e223a22222c22737461727474696d65223a22222c227469746c65223a22227d, 0, 0, 0, 0, 'Berufswahlpraktikum', '<p><strong>Pflege – mein Beruf?</strong></p>\r\n<p>Wenn du gerne mit und für Menschen arbeitest, könnte ein Pflegeberuf genau das Richtige für dich sein. Mit einem Berufswahlpraktikum bei der Spitex Region Lueg erlebst du den Spitex-Alltag hautnah. So findest du rasch heraus, ob ein Pflegeberuf der richtige Weg für dich ist.</p>\r\n<p><strong>Anmeldung</strong></p>\r\n<p>Die Anmeldung für ein Berufswahlpraktikum läuft über das Internetportal Gesundheitsberufe Kanton Bern. Nach der Anmeldung nimmt die Spitex Region Lueg mit dir Kontakt auf und organisiert gemeinsam mit dir das Berufswahlpraktikum.</p>\r\n<p><br />Link zu <a href=\"https://myoda.gesundheitsberufe-bern.ch/de/\" target=\"_blank\">myoda</a><br /><a href=\"https://gesundheitsberufe-bern.ch/schnuppern-praktika/myoda-erklaert\" target=\"_blank\">Anleitung zu myoda</a></p>', 3),
(3, 1, 1785996509, 1785502894, 0, 0, 0, 0, '', 3, 0, 0, 0, 0, NULL, 0x7b22636f6e74656e74223a22222c22656469746c6f636b223a22222c22656e6474696d65223a22222c2266655f67726f7570223a22222c2268696464656e223a22222c22737461727474696d65223a22222c227469746c65223a22227d, 0, 0, 0, 0, 'Weiterbildung', '<p>Bei uns wirst du gezielt gefördert: Wir unterstützen dich in deiner persönlichen Entwicklung und planen deinen Weg gemeinsam mit dir. Zudem bieten wir jedes Jahr Ausbildungsplätze auf HF Stufe – zusmmen mit dem Berner Bildungszentrum Pflege und XUND. Ausgebildete Berufsbildner:innen und Bildungsverantwortliche begleiten dich eng, damit du die Spitex Arbeit wirklich kennenlernst und deine Praktikumsziele erreichst.</p>', 3);

