(1, 1, 1785929808, 1785493511, 0, 0, 0, 0, '', 256, NULL, 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'default', 0, NULL, 0, 'lueg_headline_text', 0, 0, '', '', 0, 'Lueg – Dini Zuekunft ir Spitex Region Lueg', 0, '', '', '', '<p><strong>Wir suchen ausgebildete Fachkräfte, Quereinsteiger:innen und Lernende.</strong></p>\r\n<p>Ein Job bei der Spitex Region Lueg bedeutet Vielfalt, Verantwortung und Sinnhaftigkeit. Unsere Arbeit ist spannend, abwechslungsreich und zugleich anspruchsvoll – genau das macht sie so wertvoll.</p>\r\n<p>Wir unterstützen unsere Mitarbeitenden aktiv in ihrer fachlichen Weiterentwicklung und eröffnen ihnen die Möglichkeit, Verantwortung zu übernehmen, beispielsweise in Spezialfunktionen.</p>', 0, 0, NULL, NULL, 0, 0, 0, 2, NULL, 0, 0, NULL, 1, 0, NULL, NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 0, 0, 0, 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, 0, '', '', 0, 0),
(2, 1, 1785932980, 1785497882, 0, 0, 0, 0, '', 512, NULL, 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'default', 0, NULL, 0, 'lueg_podcasts', 0, 0, '', '', 0, 'Lueg – u los ine', 0, '', '', '', '<p>In dieser Podcast-Serie erzählen unsere Mitarbeitenden aus ihrem Alltag in der ambulanten Pflege – ehrlich, persönlich und mit Geschichten, die zeigen, warum genau du hier richtig bist.</p>', 0, 0, NULL, NULL, 0, 0, 0, 2, NULL, 0, 0, NULL, 1, 0, NULL, NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 2, 0, 0, 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, 0, '', '', 0, 0),
(3, 1, 1785911698, 1785502894, 0, 0, 0, 0, '', 768, NULL, 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'default', 0, NULL, 0, 'lueg_ausbildung', 0, 0, '', '', 0, 'Lueg – <br>mir biude Lernendi us', 0, '', '', '', '<p>Die Arbeit mit Menschen gibt dir echten Sinn. Damit unsere Klientinnen und Klienten jederzeit top betreut sind, bildet die Spitex Region Lueg Fachfrauen und Fachmänner Gesundheit (FaGe) aus. Bei uns wirst du Schritt für Schritt begleitet – individuell, persönlich und immer auf deinem Weg.</p>', 0, 0, NULL, NULL, 0, 0, 0, 2, NULL, 0, 0, NULL, 1, 0, NULL, NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 0, 3, 0, 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, 0, '', '', 0, 0),
(4, 1, 1785935416, 1785503461, 0, 0, 0, 0, '', 1024, NULL, 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'default', 0, NULL, 0, 'lueg_benefits', 0, 0, '', '', 0, 'Lueg – <br>was mir dir biete', 0, '', '', '', '<p>Wir sind ein moderner, innovativer Arbeitgeber mit guter Infrastruktur, zeitgemässen Arbeitsmitteln und Offenheit für neue Methoden. Wir kommunizieren auf Augenhöhe und leben eine offene, wertschätzende Teamkultur.</p>', 0, 0, NULL, NULL, 0, 0, 0, 2, NULL, 0, 0, NULL, 1, 0, NULL, NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 0, 0, 10, 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, 0, '', '', 0, 0),
(5, 1, 1785942356, 1785507434, 0, 0, 0, 0, '', 1280, NULL, 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'default', 0, NULL, 0, 'lueg_standorte', 0, 0, '', '', 0, 'Lueg – <br>wo mir si', 0, '', '', '', '<p>Das Einzugsgebiet der Spitex Region Lueg umfasst 11 Gemeinden mit rund 24\'000 Einwohnerinnen und Einwohner. Dank vier Standorten ist die Organisation in der Mitte des Emmentals präsent und bestens mit den Bedürfnissen der Bevölkerung vertraut.</p>', 0, 0, NULL, NULL, 0, 0, 0, 2, NULL, 0, 0, NULL, 1, 0, NULL, NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 0, 0, 0, 1, 'Standort Weier', 'Huttwilwestrasse 1\r\n3462 Weier i.E', 'https://maps.app.goo.gl/BbN5TwgxWsyFQfas5 _blank', 1, 'Standort Sumiswald', 'Marktgasse 5\r\n3454 Sumiswald', 'https://maps.app.goo.gl/xGh8fTqSZZBFD9BWA _blank', 1, 'Standort Affoltern', 'Dorfstrasse 12\r\n3416 Affoltern i.E.', 'https://maps.app.goo.gl/wUtu2qEUeGbW5u5y9 _blank', 1, 'Standort Hasle-Rüegsau', 'Rüegsaustrasse 8 (Parterre)\r\n3415 Rüegsauschachen', 'https://maps.app.goo.gl/ZThyteJ5aMkQEsEX6 _blank', 0, 0, '', '', 0, 0),
(6, 1, 1785746473, 1785745312, 1, 0, 0, 0, '0', 1290, NULL, 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'default', 0, NULL, 0, 'lueg_stellen', 0, 0, '', '', 0, 'Lueg – <br>üsi freie Jobs', 0, '', '', '', '<p>Ein Job bei der Spitex Region Lueg bedeutet Vielfalt, Verantwortung und Sinnhaftigkeit. Unsere Arbeit ist spannend, abwechslungsreich und zugleich anspruchsvoll. Finde hier die Stelle, die zu dir passt.</p>', 0, 0, NULL, NULL, 0, 0, 0, 2, NULL, 0, 0, NULL, 1, 0, NULL, NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 0, 0, 0, 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 5, 0, '', '', 0, 0),
(7, 1, 1785759538, 1785746473, 0, 0, 0, 0, '0', 640, NULL, 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'default', 0, NULL, 0, 'news_pi1', 0, 0, '', '', 0, 'Lueg – <br>Üsi freie Jobs', 100, '', '', '', '<p>Ein Job bei der Spitex Region Lueg bedeutet Vielfalt, Verantwortung und Sinnhaftigkeit. Unsere Arbeit ist spannend, abwechslungsreich und zugleich anspruchsvoll. Finde hier die Stelle, die zu dir passt.</p>', 0, 0, NULL, NULL, 0, 0, 0, 2, NULL, 0, 0, NULL, 1, 0, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms>\n    <data>\n        <sheet index=\"additional\">\n            <language index=\"lDEF\">\n                <field index=\"settings.detailPid\">\n                    <value index=\"vDEF\">3</value>\n                </field>\n                <field index=\"settings.listPid\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.backPid\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.limit\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.offset\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.tags\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.hidePagination\">\n                    <value index=\"vDEF\">0</value>\n                </field>\n                <field index=\"settings.list.paginate.itemsPerPage\">\n                    <value index=\"vDEF\"></value>\n                </field>\n                <field index=\"settings.topNewsFirst\">\n                    <value index=\"vDEF\">0</value>\n                </field>\n                <field index=\"settings.excludeAlreadyDisplayedNews\">\n                    <value index=\"vDEF\">0</value>\n                </field>\n                <field i