(14, 12, 1785917276, 1785916848, 0, 0, 0, 0, '', 256, '', 0, 0, 0, 0, NULL, , 0, 0, 0, 0, 'default', 0, NULL, 0, 'text', 0, 0, '', '', 0, '', 0, '', '', '', '<h2>Vielen Dank für deine Bewerbung!&nbsp;</h2>\r\n<p><br />Wir haben deine Angaben erfolgreich erhalten und werden uns so bald wie möglich bei Dir melden.</p>\r\n<p>Ihr Spitex Region Lueg</p>', 0, 0, 0, 0, 0, 0, 0, 2, NULL, 0, 0, NULL, 1, 0, NULL, NULL, '', 0, 0, '', 124, 0, 0, 0, NULL, 0, '', '', '', 0, 0, 0, 0, 0, 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, '', NULL, '', 0, 0, '', '', 0, 0);

